#!/bin/sh
# Generates ios/Config/Secrets.xcconfig (gitignored) from ../.env plus your Apple team ID.
# Usage: tools/gen_ios_secrets.sh <APPLE_TEAM_ID>
set -eu
cd "$(dirname "$0")/.."
TEAM="${1:?usage: tools/gen_ios_secrets.sh <APPLE_TEAM_ID>}"
get() { grep -E "^$1=" .env | head -1 | cut -d= -f2-; }
HOST=$(get AZURE_OPENAI_ENDPOINT | sed -e 's#^https://##' -e 's#/*$##')
umask 077
cat > ios/Config/Secrets.xcconfig <<XC
// Generated by tools/gen_ios_secrets.sh. Gitignored. Do not commit.
DEVELOPMENT_TEAM = $TEAM
AZURE_OPENAI_HOST = $HOST
AZURE_OPENAI_API_KEY = $(get AZURE_OPENAI_API_KEY)
AZURE_OPENAI_REALTIME_DEPLOYMENT = $(get AZURE_OPENAI_REALTIME_DEPLOYMENT)
AZURE_OPENAI_VISION_DEPLOYMENT = $(get AZURE_OPENAI_VISION_DEPLOYMENT)
XC
echo "wrote ios/Config/Secrets.xcconfig (host=$HOST)"
